<script lang="ts">
import {onMount} from 'svelte';
import Player from './components/Player.svelte';
import Detail from './components/Detail.svelte';
import Library from './components/Library.svelte';
import {all,people,works,events,date,pct,type Region} from './history';
import {createGalaxy,toYear,colorFor} from '../galaxy.js';
let year=$state(1843),playing=$state(false),speed=$state(1),selected=$state('manifesto-work'),region=$state<Region>('all'),span=$state(70),reduced=$state(false);
let item=$derived(all.find(x=>x.id===selected)!);
let era=$derived(year<1864?'思想与组织的萌芽':year<1917?'国际工人运动的兴起':year<1949?'革命与全球传播':year<1978?'国家建设与重大曲折':'改革、转折与新的探索');
function select(id:string,jump=false){selected=id;playing=false;if(jump){const entry=all.find(x=>x.id===id)!;year=toYear(entry.type==='work'?entry.end:entry.start);}}
function changeRegion(){if(region!=='all'&&item.region!==region)selected=people.find(p=>p.region===region)!.id;const first=works.find(w=>region==='all'||w.region===region);if(first&&year<toYear(first.start)){year=toYear(first.end);playing=false;}}
function chapter(target:number){const entry=all.find(x=>x.type!=='person'&&Number(x.start.slice(0,4))===target&&(region==='all'||x.region===region));if(entry)select(entry.id,true);else{year=target;playing=false;}}
onMount(()=>{reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;playing=!reduced;let last:number|null=null,frameId=0;
const galaxy=createGalaxy(()=>({year,playing,selected,region,span,reduced}),(id:string)=>select(id));
const visibility=()=>last=null;document.addEventListener('visibilitychange',visibility);
function frame(now:number){if(playing&&last!==null){const before=year;year=Math.min(2000,year+Math.min((now-last)/1000,.1)*speed);const reached=all.filter(x=>x.type!=='person'&&toYear(x.type==='work'?x.end:x.start)>before&&toYear(x.type==='work'?x.end:x.start)<=year&&(region==='all'||x.region===region)).sort((a,b)=>toYear(a.end)-toYear(b.end));if(reached.length)selected=reached.at(-1)!.id;if(year>=2000)playing=false;}last=playing?now:null;galaxy.draw(now);frameId=requestAnimationFrame(frame);}
frameId=requestAnimationFrame(frame);return()=>{cancelAnimationFrame(frameId);galaxy.destroy();document.removeEventListener('visibilitychange',visibility);};});
</script>
<header><a class="brand" href={import.meta.env.BASE_URL}>经纬 <span>HISTORY IN MOTION</span></a><span class="edition">交互历史图谱 / 1818—2000</span></header>
<main><section class="intro"><div><p class="eyebrow">人物 · 文献 · 相遇的星河</p><h1>历史的<span>经纬</span></h1><p class="subtitle">思想沿轨迹前行，在文献与历史的星点上交汇。</p></div><div class="year-block"><span>正在回望</span><strong id="year">{Math.floor(year)}</strong><span id="era">{era}</span></div></section>
<Player bind:year bind:playing bind:speed reset={()=>{year=1818;selected="marx";playing=false;}}/><div class="workspace galaxy-workspace"><section class="galaxy-panel"><div class="chart-head"><div><p class="eyebrow">CONSTELLATIONS OF HISTORY</p><h2>思想交汇，群星流动</h2><p>从左向右，走过人物的一生。共同写作与共同参与，让轨迹交汇。</p></div><select id="region" aria-label="地区筛选" bind:value={region} onchange={changeRegion}><option value="all">全部地区</option><option value="world">世界背景</option><option value="china">中国脉络</option></select></div><div class="galaxy-tools"><span><i class="key work-key">✦</i> 文献 <i class="key event-key">✦</i> 事件 <i class="key life-key">●</i> 人物</span><label>视野 <select id="view" aria-label="时间视野" bind:value={span}><option value={70}>跟随 · 70 年</option><option value={182}>全景 · 1818—2000</option></select></label></div><div id="sky"><canvas id="galaxy" aria-label="人物与文献动态星河，使用下方人物按钮及文献目录可查看全部内容"></canvas><div id="star-controls"></div><div class="sky-caption"><span id="sky-range"></span><span>点击星点 · 探索关联</span></div></div><div id="people-key">{#each people.filter(p=>region==='all'||p.region===region) as p}<button class:selected={selected===p.id} style={`--person-color:${colorFor(p.id)}`} onclick={()=>select(p.id)}><i></i><span>{p.name}<small>{p.start.slice(0,4)}—{p.end.slice(0,4)}</small></span></button>{/each}</div><p class="relationship-note">交汇仅表示条目所列的共同写作或共同参与，不代表思想完全一致或曾面对面相遇。</p></section><Detail item={item} {year} {select} {reduced}/></div>
<Library {region} {selected} {select}/><details class="archive"><summary>展开人物生卒与事件起止年表</summary><div class="scroll-chart"><div id="chart" style={`--progress:${pct(year)}%`}><div id="axis">{#each [1840,1860,1880,1900,1920,1940,1960,1980,2000] as y}<span style={`left:${pct(y)}%`}>{y}</span>{/each}</div><div id="rows">{#each ['person','event'] as type}<div class="group-label">{type==='person'?'人物 / 生卒区间':'事件 / 开始与结束'}</div>{#each all.filter(x=>x.type===type&&(region==='all'||x.region===region)) as x}<button class={`row ${type}`} class:future={toYear(x.start)>year} class:selected={selected===x.id} style={`--elapsed:${Math.max(0,Math.min(100,(year-toYear(x.start))/(toYear(x.end)-toYear(x.start)||1)*100))}%`} onclick={()=>select(x.id)} aria-label={`${x.name}，${date(x.start)}至${date(x.end)}`}><span class="row-name">{x.name}<small>{x.start} — {x.end}</small></span><span class="track"><span class="bar" class:point={toYear(x.end)-toYear(x.start)<1} style={`left:${pct(toYear(x.start))}%;width:${Math.max(.28,pct(toYear(x.end))-pct(toYear(x.start)))}%`}></span></span></button>{/each}{/each}</div><div id="cursor"><span></span></div></div></div></details><section class="chapters" aria-label="跳转历史阶段">{#each [[1848,'思想的形成'],[1871,'组织与实践'],[1917,'革命与传播'],[1949,'建设与曲折'],[1978,'改革与转折']] as c,i}<button onclick={()=>chapter(Number(c[0]))}><span>0{i+1} / {c[0]}</span>{c[1]} →</button>{/each}</section><footer><p>这是一份精选人物、文献与事件图谱，非完整通史。包括理论、革命、建设及重大曲折；不同人物与组织的立场并不完全相同。</p><p>日期采用公历，资料精度保留到年、月或日。事件分期如有争议，在详情中说明。展示范围至 2000 年，不意味着运动在此结束。</p></footer></main>